import { expect, test } from 'vitest'
import '../../app.css'

/**
 * The theme is wired by CSS import order alone: Web Awesome's default theme,
 * then the Livtet brand layer, then `native.css`. These assertions pin the
 * outcome, so a reordered import or a dropped `@import` fails here instead of
 * silently reverting the app to the stock palette.
 */

const token = (name: string) =>
  getComputedStyle(document.documentElement).getPropertyValue(name).trim()

test('the brand layer wins over the default palette', () => {
  // Generated by livtet-branding; the stock theme uses a different ramp.
  expect(token('--wa-color-brand-50')).toBe('oklch(45% 0.11 158)')
  expect(token('--wa-color-brand')).toBe('oklch(45% 0.11 158)')
  // The brand theme maps the focus ring onto that ramp.
  expect(token('--wa-color-focus')).toBe('oklch(50% 0.12 158)')
})

test('the brand palette carries both colour schemes', () => {
  const root = document.documentElement
  root.classList.remove('wa-dark', 'wa-light')
  expect(token('--wa-color-surface-default')).toBe('oklch(95% 0.03 65)')
  expect(token('--wa-color-text-normal')).toBe('oklch(25% 0.02 80)')

  root.classList.add('wa-dark')
  expect(token('--wa-color-surface-default')).toBe('oklch(9% 0.06 110)')
  expect(token('--wa-color-text-normal')).toBe('oklch(90% 0.015 90)')
  root.classList.remove('wa-dark')
})

test('headings keep the variable Lora family', () => {
  // The generated tokens name the static family; only the variable build is
  // installed, so app.css re-declares the heading stack on the variable name.
  expect(token('--wa-font-family-heading')).toContain('Lora Variable')
  expect(token('--wa-font-family-body')).toContain('Work Sans')
  expect(token('--wa-font-family-code')).toContain('JetBrains Mono')
})
